insert into public.preguntas (codigo_origen, categoria_id, texto, pista, explicacion, imagen, imagen_alt, fuente, url_fuente, fecha_revision, dificultad) select 'q23', c.id, '¿Qué paisaje del oeste sanjuanino ofrece una gran planicie junto a la Cordillera de los Andes?', 'También recibe el nombre Barreal Blanco.', 'La Pampa del Leoncito es una extensa planicie próxima a Barreal, famosa por su paisaje y sus vientos.', null, null, 'Administración de Parques Nacionales — Panorámica', 'https://www.argentina.gob.ar/node/437213', '2026-08-29', 'media' from public.categorias c where c.slug = 'destinos' on conflict (codigo_origen) do update set categoria_id = excluded.categoria_id, texto = excluded.texto, pista = excluded.pista, explicacion = excluded.explicacion, imagen = excluded.imagen, imagen_alt = excluded.imagen_alt, fuente = excluded.fuente, url_fuente = excluded.url_fuente, fecha_revision = excluded.fecha_revision, dificultad = excluded.dificultad;
