insert into public.preguntas (codigo_origen, categoria_id, texto, pista, explicacion, imagen, imagen_alt, fuente, url_fuente, fecha_revision, dificultad) select 'q24', c.id, 'Si alguien te invita a “hacer una escapada”, ¿qué propone?', 'No hace falta preparar una mudanza.', 'Escapada se usa para hablar de un viaje corto, generalmente de descanso o paseo.', null, null, 'Real Academia Española — Diccionario de la lengua española', 'https://dle.rae.es/escapada', '2026-08-29', 'media' from public.categorias c where c.slug = 'argentinismos' on conflict (codigo_origen) do update set categoria_id = excluded.categoria_id, texto = excluded.texto, pista = excluded.pista, explicacion = excluded.explicacion, imagen = excluded.imagen, imagen_alt = excluded.imagen_alt, fuente = excluded.fuente, url_fuente = excluded.url_fuente, fecha_revision = excluded.fecha_revision, dificultad = excluded.dificultad;
